"use strict";(self.webpackChunkwhixpdoc=self.webpackChunkwhixpdoc||[]).push([[256],{2044:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"Sidebar":[{"type":"category","label":"Introduction","collapsible":false,"items":[{"type":"link","label":"What is XMPP?","href":"/whixpdoc/docs/introduction/what-is-xmpp","docId":"introduction/what-is-xmpp","unlisted":false},{"type":"link","label":"Motivation","href":"/whixpdoc/docs/introduction/motivation","docId":"introduction/motivation","unlisted":false}],"collapsed":false},{"type":"category","label":"Server","collapsible":true,"items":[{"type":"link","label":"Selecting the right server","href":"/whixpdoc/docs/server/","docId":"server/server","unlisted":false},{"type":"link","label":"Example configuration for Ejabberd IM","href":"/whixpdoc/docs/server/configuration","docId":"server/configuration","unlisted":false},{"type":"link","label":"DirectTLS vs. StartTLS","href":"/whixpdoc/docs/server/tls","docId":"server/tls","unlisted":false},{"type":"link","label":"Host","href":"/whixpdoc/docs/server/host","docId":"server/host","unlisted":false}],"collapsed":true},{"type":"category","label":"Essentials","collapsible":false,"items":[{"type":"link","label":"Jabber Identifier","href":"/whixpdoc/docs/essentials/jid","docId":"essentials/jid","unlisted":false},{"type":"link","label":"Database","href":"/whixpdoc/docs/essentials/database","docId":"essentials/database","unlisted":false},{"type":"link","label":"Authentication","href":"/whixpdoc/docs/essentials/authentication","docId":"essentials/authentication","unlisted":false},{"type":"link","label":"Logger","href":"/whixpdoc/docs/essentials/log","docId":"essentials/log","unlisted":false},{"type":"link","label":"Connection Establishment","href":"/whixpdoc/docs/essentials/connection","docId":"essentials/connection","unlisted":false}],"collapsed":false},{"type":"category","label":"Advanced","collapsible":true,"items":[{"type":"link","label":"Building logic with Handlers","href":"/whixpdoc/docs/advanced/handlers","docId":"advanced/handlers","unlisted":false},{"type":"link","label":"Sending an initial Presence","href":"/whixpdoc/docs/advanced/presence","docId":"advanced/presence","unlisted":false},{"type":"link","label":"Sending an initial Message","href":"/whixpdoc/docs/advanced/message","docId":"advanced/message","unlisted":false},{"type":"link","label":"IQ Stanzas","href":"/whixpdoc/docs/advanced/iq","docId":"advanced/iq","unlisted":false},{"type":"link","label":"Stream Management","href":"/whixpdoc/docs/advanced/sm","docId":"advanced/sm","unlisted":false},{"type":"link","label":"Message Archive Management (MAM)","href":"/whixpdoc/docs/advanced/mam","docId":"advanced/mam","unlisted":false},{"type":"link","label":"Inbox","href":"/whixpdoc/docs/advanced/inbox","docId":"advanced/inbox","unlisted":false},{"type":"link","label":"Publish-Subscribe (PubSub)","href":"/whixpdoc/docs/advanced/pubsub","docId":"advanced/pubsub","unlisted":false},{"type":"link","label":"Client State Indication (CSI)","href":"/whixpdoc/docs/advanced/csi","docId":"advanced/csi","unlisted":false},{"type":"link","label":"Service Discovery (Disco)","href":"/whixpdoc/docs/advanced/disco","docId":"advanced/disco","unlisted":false},{"type":"link","label":"Result Set Management (RSM)","href":"/whixpdoc/docs/advanced/rsm","docId":"advanced/rsm","unlisted":false},{"type":"link","label":"Chat Markers","href":"/whixpdoc/docs/advanced/markers","docId":"advanced/markers","unlisted":false},{"type":"link","label":"Ad-Hoc Commands","href":"/whixpdoc/docs/advanced/commands","docId":"advanced/commands","unlisted":false},{"type":"link","label":"Performance Features","href":"/whixpdoc/docs/advanced/performance","docId":"advanced/performance","unlisted":false}],"collapsed":true}]},"docs":{"advanced/commands":{"id":"advanced/commands","title":"Ad-Hoc Commands","description":"Ad-Hoc Commands, defined in XEP-0050, provide a generic workflow mechanism for interacting with XMPP applications. They allow clients to execute server-side commands and processes through a standardized interface.","sidebar":"Sidebar"},"advanced/csi":{"id":"advanced/csi","title":"Client State Indication (CSI)","description":"Client State Indication (CSI), defined in XEP-0352, allows clients to indicate to the server when the user is actively using the application versus when they are inactive. This enables the server to optimize traffic delivery, saving bandwidth and resources.","sidebar":"Sidebar"},"advanced/disco":{"id":"advanced/disco","title":"Service Discovery (Disco)","description":"Service Discovery (Disco), defined in XEP-0030, allows XMPP entities to discover information about other entities on the network, including their capabilities, features, and associated items.","sidebar":"Sidebar"},"advanced/handlers":{"id":"advanced/handlers","title":"Building logic with Handlers","description":"In Whixp, using handlers is essential. Handlers form the backbone of your logic for managing communication messages, stanzas, and errors while interacting with the server. You can explore the source code of this package to gain deeper insights into the use cases for handlers.","sidebar":"Sidebar"},"advanced/inbox":{"id":"advanced/inbox","title":"Inbox","description":"The Inbox extension, defined in XEP-0430, provides a unified inbox for messages across all conversations. It allows clients to retrieve a list of active conversations and unread messages, making it easier to implement inbox-like interfaces.","sidebar":"Sidebar"},"advanced/iq":{"id":"advanced/iq","title":"IQ Stanzas","description":"IQ (Info/Query) stanzas are XMPP\'s method of requesting and modifying information, similar to HTTP\'s GET and POST methods. They form the foundation for most XMPP protocol interactions beyond simple messaging and presence.","sidebar":"Sidebar"},"advanced/mam":{"id":"advanced/mam","title":"Message Archive Management (MAM)","description":"Message Archive Management (MAM), defined in XEP-0313, allows clients to query and retrieve archived messages from the server. This enables features like message history, search, and synchronization across devices.","sidebar":"Sidebar"},"advanced/markers":{"id":"advanced/markers","title":"Chat Markers","description":"Chat Markers, defined in XEP-0333, provide a way to indicate when messages have been displayed or received. This enables read receipts and delivery notifications, similar to features found in modern messaging applications.","sidebar":"Sidebar"},"advanced/message":{"id":"advanced/message","title":"Sending an initial Message","description":"Messaging is a core functionality of the XMPP protocol, and the Whixp package provides a robust framework for building and sending messages to dedicated recipients.","sidebar":"Sidebar"},"advanced/performance":{"id":"advanced/performance","title":"Performance Features","description":"Whixp includes several performance optimizations to ensure efficient operation, especially under high message volumes. These features include message batching, rate limiting, bounded queues, and comprehensive performance metrics.","sidebar":"Sidebar"},"advanced/presence":{"id":"advanced/presence","title":"Sending an initial Presence","description":"Presence information is a core functionality of the XMPP protocol. It allows users to broadcast their availability status to others on the network. When communicating over XMPP, it is often necessary to send presence notifications to inform others (usually contacts in your roster) about your current status, such as whether you\'re online, offline, away, or busy. These presence updates help users know when they can interact with one another in real-time.","sidebar":"Sidebar"},"advanced/pubsub":{"id":"advanced/pubsub","title":"Publish-Subscribe (PubSub)","description":"Publish-Subscribe (PubSub), defined in XEP-0060, is a messaging pattern that allows efficient and scalable distribution of information. It enables entities to publish data to nodes and allows subscribers to receive real-time updates when new data is published.","sidebar":"Sidebar"},"advanced/rsm":{"id":"advanced/rsm","title":"Result Set Management (RSM)","description":"Result Set Management (RSM), defined in XEP-0059, provides a standardized way to paginate through large result sets. It\'s used by many XMPP extensions like MAM, Inbox, and PubSub to handle pagination efficiently.","sidebar":"Sidebar"},"advanced/sm":{"id":"advanced/sm","title":"Stream Management","description":"As XMPP operates over persistent TCP connections, stream management provides mechanisms to handle interruptions and maintain session continuity, ensuring that messages and presence updates are delivered even in the face of network instability.","sidebar":"Sidebar"},"essentials/authentication":{"id":"essentials/authentication","title":"Authentication","description":"In XMPP protocol, various mechanisms are employed to authenticate clients, including traditional username/password methods, token-based authentication, and more secure techniques like SASL (Simple Authentication and Security Layer). The choice of authentication mechanism can depend on the specific security requirements and the deployment environment of the XMPP server. This section delves into the authentication methods in XMPP, exploring their functionality, benefits, and the usage of several authentication methods in the Whixp package.","sidebar":"Sidebar"},"essentials/connection":{"id":"essentials/connection","title":"Connection Establishment","description":"After completing the necessary configuration, it\'s time to establish an initial connection to the XMPP server.","sidebar":"Sidebar"},"essentials/database":{"id":"essentials/database","title":"Database","description":"Whixp uses the Drift (formerly known as Moor) database framework as a built-in approach to handle the persistent parts of the package with the local system. Drift is a reactive persistence library for Dart and Flutter, built on top of SQLite.","sidebar":"Sidebar"},"essentials/jid":{"id":"essentials/jid","title":"Jabber Identifier","description":"Serves as a unique address for each user. Structurally similar to an email address, a JID comprises a username and a domain, separated by an \\"@\\" symbol\u2014for example, vsevolod@dosy.app. This format ensures that every user on the XMPP network can be uniquely identified and contacted using their JID.","sidebar":"Sidebar"},"essentials/log":{"id":"essentials/log","title":"Logger","description":"Logging outputs are essential in applications like Whixp. The library provides an ideal logging system that allows developers to observe the results of each sent stanza and communication message, as well as to be aware of any exceptions that occur while connecting to or communicating with the server. This page explains how to customize the logging system according to your needs.","sidebar":"Sidebar"},"introduction/motivation":{"id":"introduction/motivation","title":"Motivation","description":"Whixp leverages XMPP functionalities to provide a robust foundation for Dart and Flutter applications to communicate with XMPP servers. During my search for protocol support in the Flutter environment, I found that while there are officially supported SDKs for protocols like Matrix on pub.dev, XMPP lacked dedicated packages. The available XMPP packages were either discontinued or did not offer the required features for my needs.","sidebar":"Sidebar"},"introduction/what-is-xmpp":{"id":"introduction/what-is-xmpp","title":"What is XMPP?","description":"XMPP (Extensible Messaging and Presence Protocol) is an open standard communication protocol for real-time messaging and presence information.","sidebar":"Sidebar"},"server/configuration":{"id":"server/configuration","title":"Example configuration for Ejabberd IM","description":"This documentation will guide you through configuring your Ejabberd server on a local machine to establish initial connections, and send and receive stanzas.","sidebar":"Sidebar"},"server/host":{"id":"server/host","title":"Host","description":"This section explains how host selection works in Whixp.","sidebar":"Sidebar"},"server/server":{"id":"server/server","title":"Selecting the right server","description":"When selecting a server for your XMPP messaging experience, it\'s crucial to choose the right one to meet your needs. While it\'s possible to develop your own XMPP-compliant server, selecting an existing server that aligns with your requirements can simplify the process. The choice of server is often influenced by the programming language you are familiar with, as XMPP\'s extensibility allows for custom extensions and modifications.","sidebar":"Sidebar"},"server/tls":{"id":"server/tls","title":"DirectTLS vs. StartTLS","description":"DirectTLS and StartTLS are two methods used to secure communications via the Transport Layer Security (TLS) protocol. Although these terms are primarily associated with email communication, they are also applicable to XMPP. Both methods play crucial roles in ensuring secure exchanges of information in various contexts.","sidebar":"Sidebar"}}}}')}}]);